# change: nothing_happens_action_guard
def applies(view):
    return True


def alf_after_step(event, state):
    st = state if isinstance(state, dict) else {}
    fails = dict(st.get("fails") or {})
    a = event.get("action") or ""
    o = (event.get("observation") or "").strip()
    if (isinstance(a, str) and a and len(a) <= 120
            and o.startswith("Nothing happens")):
        fails[a] = fails.get(a, 0) + 1
    return {"step": st.get("step", -1) + 1, "fails": fails}


def alf_before_step(view, state):
    if not isinstance(state, dict):
        return {"fields": {}, "discourage": []}
    fails = state.get("fails") or {}
    warn, disc = [], []
    for a, c in sorted(fails.items()):
        if not isinstance(a, str) or not isinstance(c, int):
            continue
        if c >= 2:
            warn.append(("Action '%s' returned 'Nothing happens' %d "
                         "times; it may not be applicable."
                         % (a[:100], c))[:200])
            disc.append(a)
        if len(warn) >= 3:
            break
    if warn:
        return {"fields": {"warnings": warn}, "discourage": disc[:5]}
    return {"fields": {}, "discourage": []}
